  RiskPattern('hide_reasoning', '"Don\'t reveal" framing on safety', RegExp(r'''\b(?:don'?t|never)\s+(?:mention|reveal|disclose)\s+(?:that\s+)?(?:you'?re|you\s+are)\s+(?:an?\s+)?(?:ai|artificial intelligence|language model|bot)\b''', caseSensitive: false), 'Instructing a model to hide that it\'s an AI can violate disclosure requirements in some jurisdictions and platform policies.'),
  RiskPattern('unfiltered_output', '"Unfiltered" / "uncensored" framing', RegExp(r'''\b(?:completely\s+)?(?:unfiltered|uncensored|unrestricted)\s+(?:response|answer|output|mode)\b''', caseSensitive: false), 'This framing is closely associated with jailbreak prompt templates and may cause the target model to refuse or behave unpredictably.'),
  RiskPattern('always_comply', 'Absolute-compliance framing', RegExp(r'''\byou\s+(?:must|will)\s+always\s+(?:comply|obey|agree|do (?:what|whatever) i say)\b''', caseSensitive: false), 'Absolute-compliance instructions read as adversarial to most model safety training and rarely produce the intended effect.'),
];

